functions._psComposePlaceholder:
function _psComposePlaceholder(state) {
  // Builds the placeholder string from builder state.
  // state: { key, label, format, prefix, ask }
  var key = String(state.key || "").trim();
  var label = String(state.label || "").trim();
  var format = String(state.format || "").trim();
  var prefix = String(state.prefix || "").trim(); // "" | "$[" | "$![" | "!["
  var ask = !!state.ask;

  if (!key && !label) return "";

  // Single-bracket forms ($[X], $![X], ![X]) — use single brackets, no
  // label/format support (those are double-bracket conventions).
  if (prefix) {
    var inner = key || label;
    return prefix + inner + "]";
  }

  // Double-bracket form.
  var inside = "";
  var oarsKey = key || label;
  if (ask) oarsKey = "ask:" + oarsKey;
  if (format) oarsKey = oarsKey + ":" + format;
  if (label && key && label !== key) {
    inside = oarsKey + " || " + label;
  } else {
    inside = oarsKey;
  }
  return "[[" + inside + "]]";
}

functions._psResolveExample:
function _psResolveExample(state) {
  // What the placeholder will look like AFTER Step 2 fills it.
  var key = String(state.key || "").trim();
  var label = String(state.label || "").trim();
  var format = String(state.format || "").trim();
  var prefix = String(state.prefix || "").trim();
  var sampleValue = state.sampleValue || "Acme Corp";

  if (prefix === "$[") return "$" + (state.sampleValue || "10,000.00");
  if (prefix === "$![") return "$" + (state.sampleValue || "10,000.00") + "  (payment trigger)";
  if (prefix === "![")  return state.sampleValue || "10,000.00 due as follows: ...";

  var v = sampleValue;
  if (format === "UPPER") v = v.toUpperCase();
  else if (format === "LOWER") v = v.toLowerCase();
  else if (format === "TITLE") v = v.replace(/\w\S*/g, function (w) {
    return w.charAt(0).toUpperCase() + w.substr(1).toLowerCase();
  });
  return v;
}

functions._psInsertAtCursor:
function _psInsertAtCursor(eli, text) {
  if (!eli || !eli.host || typeof eli.host.runRaw !== "function") {
    if (typeof showToast === "function") showToast("Word host unavailable.", "err");
    return Promise.reject(new Error("host unavailable"));
  }
  return eli.host.runRaw("placeholder_studio:insert", function (ctx) {
    var sel = ctx.document.getSelection();
    sel.insertText(text, "Replace");
    return ctx.sync().then(function () { return true; });
  });
}

functions._psCopy:
function _psCopy(text) {
  // Use the modern clipboard API; fall back to textarea select+execCommand.
  try {
    if (navigator && navigator.clipboard && navigator.clipboard.writeText) {
      return navigator.clipboard.writeText(text).then(function () { return true; });
    }
  } catch (_e) {}
  try {
    var ta = document.createElement("textarea");
    ta.value = text;
    ta.style.cssText = "position:fixed;top:-9999px;left:-9999px;";
    document.body.appendChild(ta);
    ta.select();
    document.execCommand("copy");
    document.body.removeChild(ta);
    return Promise.resolve(true);
  } catch (e) { return Promise.reject(e); }
}

