function _psReferenceRows() {
  return [
    {
      syntax: "[[Field Name]]",
      what: "Standard fill placeholder",
      detail: "Step 2 shows a form field labeled 'Field Name'. Whatever the user types replaces this literal in the doc.",
      sample: "[[Client Name]] → Acme Corp",
    },
    {
      syntax: "[[OARS Key || Label]]",
      what: "Custom display label",
      detail: "OARS lookups + auto-fill use the LEFT side; the form shows the RIGHT side. Useful when the OARS key is technical but the lawyer-facing label should be friendly.",
      sample: "[[Counterparty Name || Client Name]] → form shows 'Client Name', OARS reads 'Counterparty Name'",
    },
    {
      syntax: "[[Field:UPPER]]",
      what: "Force uppercase",
      detail: "Always uppercase the value when inserting. Other formats: LOWER, TITLE. Use anywhere you'd use [[ ]].",
      sample: "[[Client Name:UPPER]] → ACME CORP",
    },
    {
      syntax: "[[Field:LOWER]]",
      what: "Force lowercase",
      detail: "Lowercase variant — pairs with UPPER. Same field can have both forms in the doc, both fill from one entry.",
      sample: "[[Client Name:LOWER]] → acme corp",
    },
    {
      syntax: "[[Field:TITLE]]",
      what: "Force title case",
      detail: "Capitalizes each word. Good when OARS data comes in lowercase but the doc needs Proper Noun Casing.",
