functions.showPlaceholderStudio:
function showPlaceholderStudio(eli) {
  var host = (eli && eli.ui && typeof eli.ui.claimOutput === "function")
    ? eli.ui.claimOutput()
    : document.getElementById("output");
  if (!host) return;

  // Builder state.
  var state = {
    key: "",
    label: "",
    format: "",
    prefix: "",
    ask: false,
    sampleValue: "Acme Corp",
  };

  host.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_ps_root";
  host.appendChild(root);

  // ─── Header ─────────────────────────────────────────────────────
  var header = document.createElement("div");
  header.className = "_ps_header";
  header.innerHTML =
    '<div class="_ps_eyebrow">ADMIN · TEMPLATE AUTHORING</div>' +
    '<div class="_ps_title">🏷️ Placeholder Studio</div>' +
    '<div class="_ps_sub">Build, learn, and insert <code>[[ ]]</code> placeholders. Designed for templates that flow through Build Draft Step 2.</div>';
  root.appendChild(header);

  // ─── Tab strip ──────────────────────────────────────────────────
  var tabBar = document.createElement("div");
  tabBar.className = "_ps_tabs";
  tabBar.innerHTML =
    '<button class="_ps_tab _ps_tab_active" data-ps-tab="builder">🛠 Builder</button>' +
    '<button class="_ps_tab" data-ps-tab="reference">📖 Reference</button>' +
    '<button class="_ps_tab" data-ps-tab="examples">⭐ Examples</button>' +
    '<button class="_ps_tab" data-ps-tab="tutorial">🎓 Tutorial</button>';
  root.appendChild(tabBar);

  var body = document.createElement("div");
  body.className = "_ps_body";
  root.appendChild(body);

  function _renderTab(tab) {
    Array.prototype.forEach.call(tabBar.querySelectorAll("._ps_tab"), function (b) {
      if (b.getAttribute("data-ps-tab") === tab) b.classList.add("_ps_tab_active");
      else b.classList.remove("_ps_tab_active");
    });
    body.innerHTML = "";
    if (tab === "builder")  body.appendChild(_renderBuilder());
    if (tab === "reference") body.appendChild(_renderReference());
    if (tab === "examples")  body.appendChild(_renderExamples());
    if (tab === "tutorial")  body.appendChild(_renderTutorial());
  }
  Array.prototype.forEach.call(tabBar.querySelectorAll("._ps_tab"), function (b) {
    b.onclick = function () { _renderTab(b.getAttribute("data-ps-tab")); };
  });

  // ─── BUILDER ────────────────────────────────────────────────────
  function _renderBuilder() {
    var wrap = document.createElement("div");
    wrap.className = "_ps_panel";

    wrap.innerHTML =
      '<div class="_ps_panel_intro">' +
        'Answer a few questions; the placeholder + a live preview update below. Insert at the Word cursor or copy to clipboard when ready.' +
      '</div>' +
      // Form
      '<div class="_ps_form">' +
        // Key (required)
        '<div class="_ps_field">' +
          '<label class="_ps_label">Field name <span class="_ps_req">required</span></label>' +
          '<div class="_ps_hint">What you\'re asking for. This is also the OARS lookup key (matched against the OARS data\'s field names).</div>' +
          '<input type="text" class="_ps_input" id="_ps_key" placeholder="e.g. Counterparty Name">' +
        '</div>' +
        // Label (optional)
        '<div class="_ps_field">' +
          '<label class="_ps_label">Display label <span class="_ps_opt">optional</span></label>' +
          '<div class="_ps_hint">What Step 2 shows on the form. Leave blank to use the field name. Use this when the OARS key is technical but you want a friendlier label.</div>' +
          '<input type="text" class="_ps_input" id="_ps_label" placeholder="e.g. Client Name">' +
        '</div>' +
        // Format
        '<div class="_ps_field">' +
          '<label class="_ps_label">Case format <span class="_ps_opt">optional</span></label>' +
          '<div class="_ps_hint">Force the inserted value to a specific case. The same field can appear multiple times in the doc with different formats — all fill from one entry.</div>' +
          '<div class="_ps_pillrow" id="_ps_format">' +
            '<button class="_ps_pill _ps_pill_active" data-ps-fmt="">None</button>' +
            '<button class="_ps_pill" data-ps-fmt="UPPER">UPPER CASE</button>' +
            '<button class="_ps_pill" data-ps-fmt="LOWER">lower case</button>' +
            '<button class="_ps_pill" data-ps-fmt="TITLE">Title Case</button>' +
          '</div>' +
        '</div>' +
        // Type prefix
        '<div class="_ps_field">' +
          '<label class="_ps_label">Special type <span class="_ps_opt">optional</span></label>' +
          '<div class="_ps_hint">Switches to a single-bracket variant. Use only for currency / payment fields.</div>' +
          '<div class="_ps_pillrow" id="_ps_prefix">' +
            '<button class="_ps_pill _ps_pill_active" data-ps-pfx="">Standard [[ ]]</button>' +
            '<button class="_ps_pill" data-ps-pfx="$[">$[ ] currency</button>' +
            '<button class="_ps_pill" data-ps-pfx="$![">$![ ] payment trigger</button>' +
            '<button class="_ps_pill" data-ps-pfx="![">![ ] payment candidate</button>' +
          '</div>' +
        '</div>' +
        // Ask marker
        '<div class="_ps_field">' +
          '<label class="_ps_label">Lawyer-only question <span class="_ps_opt">optional</span></label>' +
          '<div class="_ps_hint">Highlights this field in Step 2 as a question the lawyer must answer (not auto-fillable from OARS).</div>' +
          '<label class="_ps_check">' +
            '<input type="checkbox" id="_ps_ask"> Mark as <code>ask:</code> question' +
          '</label>' +
        '</div>' +
        // Sample value (for preview)
        '<div class="_ps_field">' +
          '<label class="_ps_label">Sample value <span class="_ps_opt">preview only</span></label>' +
          '<div class="_ps_hint">Used to show what the placeholder will look like after Step 2 fills it. Does NOT go into the doc.</div>' +
          '<input type="text" class="_ps_input" id="_ps_sample" placeholder="Acme Corp" value="Acme Corp">' +
        '</div>' +
      '</div>' +
      // Output card
      '<div class="_ps_outcard">' +
        '<div class="_ps_out_label">YOUR PLACEHOLDER</div>' +
        '<div class="_ps_out_value" id="_ps_out">[[Counterparty Name]]</div>' +
        '<div class="_ps_out_label _ps_out_label_mt">PREVIEW AFTER STEP 2 FILL</div>' +
        '<div class="_ps_out_preview" id="_ps_preview">Acme Corp</div>' +
        '<div class="_ps_out_actions">' +
          '<button class="_ps_btn _ps_btn_primary" id="_ps_insert">📌 Insert at Cursor</button>' +
          '<button class="_ps_btn _ps_btn_secondary" id="_ps_copy">📋 Copy</button>' +
          '<button class="_ps_btn _ps_btn_ghost" id="_ps_reset">↺ Reset</button>' +
        '</div>' +
        '<div class="_ps_out_status" id="_ps_status"></div>' +
      '</div>';

    // Wire form controls.
    setTimeout(function () {
      var keyEl    = document.getElementById("_ps_key");
      var labelEl  = document.getElementById("_ps_label");
      var sampleEl = document.getElementById("_ps_sample");
      var askEl    = document.getElementById("_ps_ask");
      var fmtRow   = document.getElementById("_ps_format");
      var pfxRow   = document.getElementById("_ps_prefix");
      var out      = document.getElementById("_ps_out");
      var preview  = document.getElementById("_ps_preview");
      var status   = document.getElementById("_ps_status");
      var insertBtn= document.getElementById("_ps_insert");
      var copyBtn  = document.getElementById("_ps_copy");
      var resetBtn = document.getElementById("_ps_reset");
      if (!keyEl) return;

      function _refresh() {
        state.key    = keyEl.value;
        state.label  = labelEl.value;
        state.sampleValue = sampleEl.value || "Acme Corp";
        state.ask    = askEl.checked;
        var composed = _psComposePlaceholder(state);
        out.textContent = composed || "(fill in a field name above)";
        out.classList.toggle("_ps_out_value_empty", !composed);
        preview.textContent = composed ? _psResolveExample(state) : "—";
        // Some pills disabled when prefix is non-standard.
        var pfxActive = state.prefix !== "";
        Array.prototype.forEach.call(fmtRow.querySelectorAll("._ps_pill"), function (p) {
          if (pfxActive && p.getAttribute("data-ps-fmt") !== "") {
            p.classList.add("_ps_pill_disabled");
            p.disabled = true;
          } else {
            p.classList.remove("_ps_pill_disabled");
            p.disabled = false;
          }
        });
        askEl.disabled = pfxActive;
        askEl.parentNode.classList.toggle("_ps_check_disabled", pfxActive);
      }

      keyEl.oninput = _refresh;
      labelEl.oninput = _refresh;
      sampleEl.oninput = _refresh;
      askEl.onchange = _refresh;

      function _wirePillRow(row, attr, key) {
        Array.prototype.forEach.call(row.querySelectorAll("._ps_pill"), function (p) {
          p.onclick = function () {
            if (p.disabled) return;
            Array.prototype.forEach.call(row.querySelectorAll("._ps_pill"), function (x) {
              x.classList.remove("_ps_pill_active");
            });
            p.classList.add("_ps_pill_active");
            state[key] = p.getAttribute(attr) || "";
            _refresh();
          };
        });
      }
      _wirePillRow(fmtRow, "data-ps-fmt", "format");
      _wirePillRow(pfxRow, "data-ps-pfx", "prefix");

      function _setStatus(msg, kind) {
        status.textContent = msg;
        status.className = "_ps_out_status _ps_out_status_" + (kind || "ok");
        setTimeout(function () {
          if (status.textContent === msg) {
            status.textContent = "";
            status.className = "_ps_out_status";
          }
        }, 2500);
      }

      insertBtn.onclick = function () {
        var text = out.textContent;
        if (!text || /fill in a field/i.test(text)) {
          _setStatus("Add a field name first.", "warn"); return;
        }
        _psInsertAtCursor(eli, text).then(function () {
          _setStatus("✓ Inserted at cursor.", "ok");
        }).catch(function (err) {
          _setStatus("Insert failed: " + (err && err.message || "unknown"), "err");
        });
      };
      copyBtn.onclick = function () {
        var text = out.textContent;
        if (!text || /fill in a field/i.test(text)) {
          _setStatus("Add a field name first.", "warn"); return;
        }
        _psCopy(text).then(function () {
          _setStatus("✓ Copied to clipboard.", "ok");
        }).catch(function () {
          _setStatus("Copy failed.", "err");
        });
      };
      resetBtn.onclick = function () {
        keyEl.value = ""; labelEl.value = ""; sampleEl.value = "Acme Corp";
        askEl.checked = false;
        state = { key: "", label: "", format: "", prefix: "", ask: false, sampleValue: "Acme Corp" };
        Array.prototype.forEach.call(fmtRow.querySelectorAll("._ps_pill"), function (p) {
          p.classList.toggle("_ps_pill_active", p.getAttribute("data-ps-fmt") === "");
        });
        Array.prototype.forEach.call(pfxRow.querySelectorAll("._ps_pill"), function (p) {
          p.classList.toggle("_ps_pill_active", p.getAttribute("data-ps-pfx") === "");
        });
        _refresh();
      };

      _refresh();
    }, 0);

    return wrap;
  }

  // ─── REFERENCE ──────────────────────────────────────────────────
  function _renderReference() {
    var wrap = document.createElement("div");
    wrap.className = "_ps_panel";
    var rows = _psReferenceRows();
    var html =
      '<div class="_ps_panel_intro">' +
        'Every placeholder syntax ELI understands, with what it does, when to use it, and an example.' +
      '</div>' +
      '<div class="_ps_reftable">';
    rows.forEach(function (r) {
      html +=
        '<div class="_ps_refrow">' +
          '<div class="_ps_refsyntax"><code>' + _psEsc(r.syntax) + '</code>' +
            '<button class="_ps_refcopy" data-ps-copy="' + _psEsc(r.syntax) + '" title="Copy syntax">📋</button>' +
          '</div>' +
          '<div class="_ps_refcontent">' +
            '<div class="_ps_refwhat">' + _psEsc(r.what) + '</div>' +
            '<div class="_ps_refdetail">' + _psEsc(r.detail) + '</div>' +
            '<div class="_ps_refsample">' + _psEsc(r.sample) + '</div>' +
          '</div>' +
        '</div>';
    });
    html += '</div>';
    wrap.innerHTML = html;
    setTimeout(function () {
      Array.prototype.forEach.call(wrap.querySelectorAll("._ps_refcopy"), function (b) {
        b.onclick = function () {
          var t = b.getAttribute("data-ps-copy");
          _psCopy(t).then(function () {
            var orig = b.textContent;
            b.textContent = "✓";
            setTimeout(function () { b.textContent = orig; }, 1200);
          });
        };
      });
    }, 0);
    return wrap;
  }

  // ─── EXAMPLES ───────────────────────────────────────────────────
  function _renderExamples() {
    var wrap = document.createElement("div");
    wrap.className = "_ps_panel";
    var ex = _psExamples();
    var html =
      '<div class="_ps_panel_intro">' +
        'Copy any of these ready-to-paste patterns. Click the placeholder to copy; click Insert to drop it at your Word cursor.' +
      '</div>' +
      '<div class="_ps_examples">';
    ex.forEach(function (e, i) {
