            '<button class="_ps_btn _ps_btn_primary _ps_btn_sm" data-ps-ex-insert="' + i + '">📌 Insert</button>' +
            '<button class="_ps_btn _ps_btn_secondary _ps_btn_sm" data-ps-ex-copy="' + i + '">📋 Copy</button>' +
          '</div>' +
        '</div>';
    });
    html += '</div>';
    wrap.innerHTML = html;
    setTimeout(function () {
      Array.prototype.forEach.call(wrap.querySelectorAll("[data-ps-ex-insert]"), function (b) {
        b.onclick = function () {
          var i = Number(b.getAttribute("data-ps-ex-insert")) || 0;
