            var orig = b.textContent; b.textContent = "✓ Copied";
            setTimeout(function () { b.textContent = orig; }, 1500);
          });
        };
      });
    }, 0);
    return wrap;
  }

  // ─── TUTORIAL ───────────────────────────────────────────────────
  function _renderTutorial() {
    var wrap = document.createElement("div");
    wrap.className = "_ps_panel";
    wrap.innerHTML =
      '<div class="_ps_tut">' +
        '<h2>How placeholders work</h2>' +
        '<p>Placeholders are <b>literal text in your template</b> that Build Draft replaces with real values at fill time. They run in two distinct passes:</p>' +
        '<div class="_ps_tut_grid">' +
          '<div class="_ps_tut_card">' +
            '<div class="_ps_tut_step">Step 1 · Logic</div>' +
            '<div class="_ps_tut_what">{{ }} placeholders</div>' +
            '<p>Used for conditional content — <code>{{IF: condition}}</code>, <code>{{DEF: key=default | options}}</code>, <code>{{TITLE: NDA}}</code>. The user answers a wizard form; ELI resolves the conditions and rewrites the doc BEFORE Step 2 starts.</p>' +
          '</div>' +
          '<div class="_ps_tut_card">' +
            '<div class="_ps_tut_step">Step 2 · Fill</div>' +
            '<div class="_ps_tut_what">[[ ]] placeholders ← THIS TOOL</div>' +
            '<p>Plain field-fill. Each <code>[[Field Name]]</code> shows up as a form field. The user (or OARS auto-fill) provides values; ELI does a literal find-and-replace.</p>' +
          '</div>' +
        '</div>' +
        '<h2>Anatomy of a [[ ]] placeholder</h2>' +
        '<p>The simplest form is <code>[[Field Name]]</code>. The full grammar:</p>' +
        '<div class="_ps_grammar">' +
          '<code>[[' +
            '<span class="_ps_g_part _ps_g_ask">ask:</span>' +
            '<span class="_ps_g_part _ps_g_key">OARS Key</span>' +
            '<span class="_ps_g_part _ps_g_fmt">:UPPER</span>' +
            '<span class="_ps_g_part _ps_g_sep"> || </span>' +
            '<span class="_ps_g_part _ps_g_label">Form Label</span>' +
          ']]</code>' +
        '</div>' +
        '<ul class="_ps_partlist">' +
          '<li><span class="_ps_dot _ps_dot_ask"></span><b>ask:</b> — optional. Marks this as a lawyer question (highlighted in Step 2).</li>' +
          '<li><span class="_ps_dot _ps_dot_key"></span><b>OARS Key</b> — required. The field name. Matched against OARS data for auto-fill.</li>' +
          '<li><span class="_ps_dot _ps_dot_fmt"></span><b>:UPPER / :LOWER / :TITLE</b> — optional. Forces case. Same field can appear with different formats; all fill from one entry.</li>' +
          '<li><span class="_ps_dot _ps_dot_label"></span><b>|| Form Label</b> — optional. What the lawyer sees on the Step 2 form. Defaults to the OARS Key if omitted.</li>' +
        '</ul>' +
        '<h2>Auto-fill from OARS</h2>' +
        '<p>If the active document carries OARS data, Step 2 tries to pre-fill every field by matching the OARS Key against the OARS data field names (case-insensitive, fuzzy). For common fields (Counterparty Name, Effective Date, Fee Amount, Agreement Type), this means zero typing.</p>' +
        '<h2>Multi-occurrence: one entry, many fills</h2>' +
        '<p>If <code>[[Client Name]]</code> appears 5 times in the doc, the form shows ONE input — all 5 fill from it. If <code>[[Client Name:UPPER]]</code> also appears, it shares the same value (uppercased). The form de-duplicates so the user only sees one field per OARS key.</p>' +
        '<h2>Currency &amp; payments</h2>' +
        '<p>For dollar amounts, use the single-bracket variants:</p>' +
        '<ul>' +
          '<li><code>$[Fee]</code> — auto-formats the number as <code>$XX,XXX.XX</code>.</li>' +
          '<li><code>$![Initial Payment]</code> — same as above, plus opens the payment-schedule helper at fill time.</li>' +
          '<li><code>![First Payment]</code> — payment candidate; replaced with "due as follows: …" from the schedule modal.</li>' +
        '</ul>' +
        '<h2>Best practices</h2>' +
        '<ul class="_ps_best">' +
          '<li><b>Use canonical names</b> — match OARS field names exactly (e.g. "Counterparty Name", not "client" or "party"). The system\'s fuzzy match helps but exact is most reliable.</li>' +
          '<li><b>Add labels for clarity</b> — if your OARS key is technical, use <code>[[OARS Key || Friendly Label]]</code> so the form is readable.</li>' +
          '<li><b>Cap-format defined terms</b> — <code>[[Client Name:UPPER]] ("Client Name")</code> is the standard pattern for first appearance of a defined term.</li>' +
          '<li><b>Don\'t nest</b> — <code>[[[[ ]] inside [[ ]]]]</code> doesn\'t work. Each placeholder is matched as a literal string.</li>' +
          '<li><b>Whitespace matters</b> — <code>[[ Client ]]</code> (with spaces) is a different placeholder from <code>[[Client]]</code>. Trim before placing.</li>' +
          '<li><b>Test in Build Draft</b> — paste your template into a Word doc, open Build Draft, run Step 2 — check the form fields look right and OARS auto-fill works as expected.</li>' +
        '</ul>' +
        '<h2>Switch to the Builder</h2>' +
        '<p>The <b>🛠 Builder</b> tab walks you through the choices interactively. The <b>📖 Reference</b> tab is the full syntax cheat sheet. The <b>⭐ Examples</b> tab has ready-to-paste patterns for common cases.</p>' +
      '</div>';
    return wrap;
  }

  // Default to Builder.
  _renderTab("builder");
}

jsonTools.init:
function init(eli) {
  if (!eli || !eli.tools || !eli.register) return;

  function _show() {
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedPlaceholderStudio"); } catch (e) {}
    try { if (eli.fsm && eli.fsm.getCurrent && eli.fsm.getCurrent() === "idle") eli.fsm.transition("scanning"); } catch (e) {}
    if (typeof window.showPlaceholderStudio !== "function") {
      eli.log.event("tool", "placeholder_studio_fn_missing", {});
      if (typeof showToast === "function") showToast("Placeholder Studio failed to load", "err");
      return;
    }
    try { window.showPlaceholderStudio(eli); }
    catch (e) {
      eli.log.event("tool", "placeholder_studio_failed", { msg: e && e.message });
      if (typeof showToast === "function") showToast("Open failed: " + (e.message || "unknown"), "err");
    }
  }

  eli.register({
    tile: { app_placeholder_studio: _show },
    placeholder_studio: { open: _show },
  });

  eli.log.event("tool", "placeholder_studio_initialized", {});
}

jsonTools.css:
/* tools/placeholder_studio/style.css — Premium admin UI for the
   [[ ]] placeholder builder. Navy/gold per project accent rules. */

._ps_root {
  font-family: Inter, "Segoe UI", system-ui, sans-serif;
  color: #0f172a;
  background: #f8fafc;
  padding: 0;
}

/* ─── Header ─────────────────────────────────────────────────────── */
._ps_header {
  background: linear-gradient(135deg, #0d1b2a 0%, #1b263b 100%);
  color: #fff;
  padding: 20px 22px 18px;
  border-bottom: 3px solid #c9a227;
}
._ps_eyebrow {
  font: 700 9px/1 Inter, sans-serif;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: #c9a227;
  margin-bottom: 6px;
}
._ps_title {
  font: 800 22px/1.1 Georgia, serif;
  margin-bottom: 6px;
}
._ps_sub {
  font: 400 12.5px/1.5 Inter, sans-serif;
  color: #cbd5e1;
}
._ps_sub code {
  background: rgba(201, 162, 39, 0.18);
  color: #fde68a;
  padding: 1px 6px;
  border-radius: 3px;
  font: 600 11.5px Consolas, monospace;
}

/* ─── Tabs ───────────────────────────────────────────────────────── */
._ps_tabs {
  display: flex;
  gap: 6px;
  padding: 12px 16px 0;
  background: #f1f5f9;
  border-bottom: 1px solid #e2e8f0;
}
._ps_tab {
  background: transparent;
  border: 1px solid transparent;
  border-bottom: none;
  padding: 8px 14px;
  border-radius: 6px 6px 0 0;
  font: 600 12px Inter, sans-serif;
  color: #64748b;
  cursor: pointer;
  transition: all 0.12s ease;
}
._ps_tab:hover { color: #1e293b; background: #e2e8f0; }
._ps_tab_active {
  background: #fff;
  border-color: #e2e8f0;
  color: #0f172a;
  position: relative;
  top: 1px;
}

._ps_body {
  background: #fff;
  min-height: 400px;
}
._ps_panel {
  padding: 20px 22px 28px;
}
._ps_panel_intro {
  font: 400 13px/1.5 Inter, sans-serif;
  color: #475569;
  background: #f8fafc;
  border-left: 3px solid #c9a227;
  padding: 10px 14px;
  border-radius: 0 4px 4px 0;
  margin-bottom: 18px;
}

/* ─── Form (Builder) ─────────────────────────────────────────────── */
._ps_form {
  display: grid;
  grid-template-columns: 1fr;
  gap: 16px;
  max-width: 720px;
}
._ps_field {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 6px;
  padding: 12px 14px;
}
._ps_label {
  display: block;
  font: 700 11px/1 Inter, sans-serif;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: #1d3a8a;
  margin-bottom: 4px;
}
._ps_req {
  font-weight: 700;
  font-size: 9px;
  letter-spacing: 0.1em;
  background: #fee2e2;
  color: #991b1b;
  padding: 1px 6px;
  border-radius: 3px;
  margin-left: 6px;
  text-transform: uppercase;
}
._ps_opt {
  font-weight: 700;
  font-size: 9px;
  letter-spacing: 0.1em;
  background: #f1f5f9;
  color: #64748b;
  padding: 1px 6px;
  border-radius: 3px;
  margin-left: 6px;
  text-transform: uppercase;
}
._ps_hint {
  font: 400 11.5px/1.5 Inter, sans-serif;
  color: #64748b;
  margin: 4px 0 8px;
}
._ps_input {
  width: 100%;
  padding: 8px 10px;
  font: 400 13px Inter, sans-serif;
  border: 1px solid #cbd5e1;
  border-radius: 4px;
  background: #fff;
  color: #0f172a;
  box-sizing: border-box;
  transition: border-color 0.12s ease, box-shadow 0.12s ease;
}
._ps_input:focus {
  outline: none;
  border-color: #1d3a8a;
  box-shadow: 0 0 0 3px rgba(29, 58, 138, 0.12);
}
._ps_check {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font: 400 13px Inter, sans-serif;
  color: #0f172a;
  cursor: pointer;
}
._ps_check input { cursor: pointer; }
._ps_check code {
  font: 600 12px Consolas, monospace;
  background: #f1f5f9;
  padding: 1px 6px;
  border-radius: 3px;
  color: #1d3a8a;
}
._ps_check_disabled { opacity: 0.45; cursor: not-allowed; }
._ps_check_disabled input { cursor: not-allowed; }

/* ─── Pill rows (format / prefix) ────────────────────────────────── */
._ps_pillrow {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}
._ps_pill {
  background: #fff;
  border: 1px solid #cbd5e1;
  color: #475569;
  padding: 6px 12px;
  border-radius: 16px;
  font: 600 11.5px Inter, sans-serif;
  cursor: pointer;
  transition: all 0.12s ease;
}
._ps_pill:hover:not(._ps_pill_disabled) {
  border-color: #94a3b8;
  background: #f8fafc;
}
._ps_pill_active {
  background: linear-gradient(180deg, #1d3a8a 0%, #14306a 100%);
  border-color: #14306a;
  color: #fff;
  box-shadow: 0 1px 3px rgba(29, 58, 138, 0.25);
}
._ps_pill_disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* ─── Output card ────────────────────────────────────────────────── */
._ps_outcard {
  margin-top: 20px;
  background: linear-gradient(135deg, #0d1b2a 0%, #1b263b 100%);
  border: 1px solid #c9a227;
  border-radius: 8px;
  padding: 18px 20px;
  box-shadow: 0 4px 14px rgba(13, 27, 42, 0.18);
  max-width: 720px;
}
._ps_out_label {
  font: 700 9.5px/1 Inter, sans-serif;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: #c9a227;
  margin-bottom: 8px;
}
._ps_out_label_mt { margin-top: 14px; }
._ps_out_value {
  font: 700 18px/1.3 Consolas, "Courier New", monospace;
  color: #fde68a;
  background: rgba(0, 0, 0, 0.25);
  padding: 12px 14px;
  border-radius: 5px;
  border: 1px solid rgba(201, 162, 39, 0.3);
  word-break: break-all;
  user-select: all;
}
._ps_out_value_empty {
  color: #94a3b8;
  font-style: italic;
  font-weight: 400;
  font-size: 14px;
}
._ps_out_preview {
  font: 500 14px/1.4 Georgia, serif;
  color: #fff;
  background: rgba(255, 255, 255, 0.06);
  padding: 10px 14px;
  border-radius: 5px;
  border: 1px solid rgba(255, 255, 255, 0.12);
}
._ps_out_actions {
  display: flex;
  gap: 8px;
  margin-top: 16px;
  flex-wrap: wrap;
}
._ps_out_status {
  margin-top: 10px;
  font: 600 12px Inter, sans-serif;
  min-height: 18px;
  color: #cbd5e1;
}
._ps_out_status_ok { color: #86efac; }
._ps_out_status_warn { color: #fde047; }
._ps_out_status_err { color: #fca5a5; }

/* ─── Buttons ────────────────────────────────────────────────────── */
._ps_btn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 9px 16px;
  border-radius: 5px;
  font: 700 12px Inter, sans-serif;
  cursor: pointer;
  transition: all 0.1s ease;
  border: 1px solid transparent;
}
._ps_btn_primary {
  background: linear-gradient(180deg, #c9a227 0%, #a78420 100%);
  color: #1a1207;
  border-color: #8a6c1a;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.18);
}
._ps_btn_primary:hover {
  background: linear-gradient(180deg, #dab432 0%, #b8941c 100%);
  transform: translateY(-1px);
  box-shadow: 0 3px 6px rgba(0, 0, 0, 0.22);
}
._ps_btn_secondary {
  background: linear-gradient(180deg, #fafaf8, #e9e6da);
  color: #3a3528;
  border-color: #c4bea8;
}
._ps_btn_secondary:hover {
  background: linear-gradient(180deg, #fcfaf2, #ddd9c8);
  transform: translateY(-1px);
}
._ps_btn_ghost {
  background: transparent;
  color: #cbd5e1;
  border-color: rgba(255, 255, 255, 0.18);
}
._ps_btn_ghost:hover {
  background: rgba(255, 255, 255, 0.06);
  color: #fff;
}
._ps_btn_sm {
  padding: 6px 10px;
  font-size: 11px;
}

/* ─── Reference table ────────────────────────────────────────────── */
._ps_reftable {
  display: grid;
  gap: 8px;
}
._ps_refrow {
  display: grid;
  grid-template-columns: minmax(160px, 220px) 1fr;
  gap: 16px;
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 6px;
  padding: 14px 16px;
  align-items: start;
}
._ps_refsyntax {
  display: flex;
  align-items: center;
  gap: 8px;
}
._ps_refsyntax code {
  font: 600 12.5px Consolas, monospace;
  background: linear-gradient(135deg, #0d1b2a 0%, #1b263b 100%);
  color: #fde68a;
  padding: 6px 10px;
  border-radius: 4px;
  display: inline-block;
}
._ps_refcopy {
  background: transparent;
  border: 1px solid #e2e8f0;
  color: #64748b;
  width: 26px;
  height: 26px;
  border-radius: 4px;
  cursor: pointer;
  font-size: 12px;
  padding: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
._ps_refcopy:hover { background: #f1f5f9; color: #0f172a; }
._ps_refwhat {
  font: 700 13px Inter, sans-serif;
  color: #1d3a8a;
  margin-bottom: 4px;
}
._ps_refdetail {
  font: 400 12.5px/1.55 Inter, sans-serif;
  color: #475569;
  margin-bottom: 6px;
}
._ps_refsample {
  font: 400 11.5px/1.4 Consolas, monospace;
  color: #6b624a;
  background: #fdf8e8;
  padding: 6px 10px;
  border-left: 3px solid #c9a227;
  border-radius: 0 3px 3px 0;
}

/* ─── Examples ────────────────────────────────────────────────────── */
._ps_examples {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 12px;
}
._ps_example {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 6px;
  padding: 14px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
._ps_extitle {
  font: 700 12.5px Inter, sans-serif;
  color: #1d3a8a;
}
._ps_extext code {
  font: 600 12px Consolas, monospace;
  background: linear-gradient(135deg, #0d1b2a 0%, #1b263b 100%);
  color: #fde68a;
  padding: 6px 10px;
  border-radius: 4px;
  display: inline-block;
  word-break: break-all;
}
._ps_exdesc {
  font: 400 11.5px/1.45 Inter, sans-serif;
  color: #64748b;
  flex: 1;
}
._ps_exactions {
  display: flex;
  gap: 6px;
}

/* ─── Tutorial ───────────────────────────────────────────────────── */
._ps_tut {
  max-width: 760px;
  font: 400 13.5px/1.6 Inter, sans-serif;
  color: #1e293b;
}
._ps_tut h2 {
  font: 800 17px/1.2 Georgia, serif;
  color: #0f172a;
  margin: 22px 0 10px;
  border-bottom: 2px solid #c9a227;
  padding-bottom: 6px;
}
._ps_tut h2:first-child { margin-top: 4px; }
