._ps_tut code {
  font: 600 12px Consolas, monospace;
  background: #f1f5f9;
  color: #1d3a8a;
  padding: 1px 6px;
  border-radius: 3px;
}
._ps_tut ul {
  margin: 8px 0;
  padding-left: 22px;
}
._ps_tut li { margin-bottom: 6px; }
._ps_tut_grid {
