  text-align: center;
}
._ps_grammar code {
  background: transparent;
  color: #fff;
  font: 700 16px Consolas, monospace;
  padding: 0;
}
._ps_g_part { display: inline-block; }
._ps_g_ask { color: #fca5a5; }
._ps_g_key { color: #fde68a; border-bottom: 2px solid #c9a227; }
._ps_g_fmt { color: #93c5fd; }
